\label{lem:D_average_rep}
    For every $\beta > 0$, the discriminant $\mathcal{D}$ can be written as
    \begin{align}\label{eq:averaging_identy}
        \mathcal{D} = 2 \int_{\mathbb R} \frac{2}{\beta} \sech\left(\frac{2\pi s}{\beta}\right) e^{is \text{ad}_H} \mathcal{K}_f e^{-is \text{ad}_H} ds,
    \end{align}
    where $e^{is \operatorname{ad}_H} (X) = e^{isH} X e^{-isH}$.

We may rewrite \(A_i=e^{-\beta H/4}Y_i e^{\beta H/4}\) and
    \(A_i^\dagger=e^{\beta H/4}Y_i e^{-\beta H/4}\).
    Substituting the Lindblad generator into the definition of $\mathcal{D}$, and cancelling the scalar normalization factors from $\rho^{\pm 1/4}$, we obtain 
    \begin{align}\label{eq:discriminant_plugin}
        \mathcal{D}(X) = e^{\beta H/4} \left(\frac{1}{2} \sum_i A_i^\dagger A_i + iB\right) e^{-\beta H/4} X + X e^{-\beta H/4} \left(\frac{1}{2}\sum_i A_i^\dagger A_i - iB\right)e^{\beta H/4} - \sum_i Y_i X Y_i.
    \end{align}
    In particular, the jump term becomes $Y_iXY_i$ because 
    \begin{align}
        e^{\beta H/4} A_i e^{-\beta H/4} = e^{-\beta H/4} A_i^{\dagger} e^{\beta H/4} = Y_i.
    \end{align}
    The choice of $B = \frac{i}{2} \tanh{\left(\frac{\beta}{4} \text{ad}_H\right)} \left(\sum_{i=1}^N A_i^\dagger A_i\right)$ simplifies the two remaining terms.
    Indeed, 
    \begin{align}
         e^{\pm (\beta/4) \text{ad}_H} \left(\frac{1}{2} \sum_i A_i^{\dagger} A_i \pm iB\right) &= \frac{1}{2} e^{\pm (\beta/4) \text{ad}_H} \left(I \mp  \tanh\left(\frac{\beta}{4} \text{ad}_H\right)\right) \left(\sum_i A_i^\dagger A_i\right) \\
         &= \frac{1}{2} \sech\left(\frac{\beta}{4} \text{ad}_H\right) \left(\sum_i A_i^\dagger A_i\right).
    \end{align}
    The last equality follows by the scalar identity $e^{\pm x} (1\mp \tanh{x}) = \sech(x)$.
    Therefore, \eqref{eq:discriminant_plugin} becomes 
    \begin{align}\label{eq:discriminant_decomp}
        \mathcal{D}(X) = \frac{1}{2} \sum_i \left[\sech\left(\frac{\beta}{4} \text{ad}_H\right) (A_i^\dagger A_i)\right]X + \frac{1}{2} \sum_i X\left[\sech\left(\frac{\beta}{4} \text{ad}_H\right) (A_i^\dagger A_i)\right]- \sum_i Y_i X Y_i.
    \end{align}
    We now verify \eqref{eq:averaging_identy} by averaging the corresponding expansion of $\mathcal{K}_f$:
    \begin{align}\label{eq:pseudo_lindblad_filtered}
        \mathcal{K}_f(X) = \frac{1}{4}\sum_i (A_i^\dagger A_i X + XA_i^\dagger A_i - A_i^\dagger X A_i^\dagger - A_i X A_i).
    \end{align}
    Since $e^{is \text{ad}_H}(X) = e^{isH}X e^{-isH}$, conjugating $\mathcal{K}_f$ by $e^{is \text{ad}_H}$ conjugates each matrix multiplying $X$ by $e^{isH}$.
    The effect of averaging these conjugations is determined by the scalar Fourier identity 
    \begin{align}\label{eq:scalar_fourier}
        \int_{\mathbb R} \frac{2}{\beta} \sech\left(\frac{2\pi s}{\beta}\right) e^{is\omega} ds = \sech\left(\frac{\beta \omega }{4}\right).
    \end{align}
    To recover the first two terms in \eqref{eq:discriminant_decomp}, spectral calculus and \eqref{eq:scalar_fourier} give 
    \begin{align}
        \int_{\mathbb R} \frac{2}{\beta} \sech\left(\frac{2\pi s}{\beta}\right) e^{is H} A_i^\dagger A_i e^{-isH} ds = \sech\left(\frac{\beta}{4} \text{ad}_H\right)(A_i^\dagger A_i).
    \end{align}
    Thus, their averages produce the left and right multiplication terms that appear in \eqref{eq:discriminant_decomp}.
    To treat the remaining two cross terms, choose an orthonormal energy eigenbasis $H \ket{m} = E_m \ket{m}$. 
    The definitions of $A_i$ and $Y_i$ imply 
    \begin{align}
        (A_i)_{mp} = e^{-\beta(E_m - E_p)/4} (Y_i)_{mp}, \quad (A_i^\dagger)_{mp} = e^{\beta(E_m - E_p)/4} (Y_i)_{mp}.
    \end{align}
    For the map $X \to A_i X A_i + A_i^\dagger X A_i^\dagger$, the coefficient taking $\ket{p}\bra{q}$ to $\ket{m}\bra{n}$ is therefore 
    \begin{align}
        (A_i)_{mp} (A_i)_{qn} + (A_i^\dagger)_{mp} (A_i^\dagger)_{qn} = 2 \cosh\left(\frac{\beta \omega }{4}\right) (Y_i)_{mp} (Y_i)_{qn},
    \end{align}
    where $\omega = (E_m - E_p) + (E_q - E_n)$.
    Conjugating this map by $e^{is \text{ad}_H}$ multiplies the coefficient by 
    \begin{align}
        e^{is ((E_m - E_n) - (E_p - E_q))} = e^{is\omega}.
    \end{align}
    Combining with \eqref{eq:scalar_fourier}, the scalar factor after averaging is then 
    \begin{align}
        2\cosh\left(\frac{\beta \omega}{4}\right) \int_{\mathbb R} \frac{2}{\beta} \sech\left(\frac{2\pi s}{\beta}\right)e^{is\omega} ds = 2\cosh\left(\frac{\beta\omega}{4} \right)\sech\left(\frac{\beta \omega}{4}\right) = 2.
    \end{align}
    We then get that the average of $X \to A_i X A_i + A_i^\dagger X A_i^\dagger$ is $X \to 2Y_i X Y_i$.
    Combining these calculations with the signs and the factor of $1/4$ in \eqref{eq:pseudo_lindblad_filtered}, we obtain the desired expression in \eqref{eq:averaging_identy}.

\label{lem:filtered_to_lind_gap}
    Assume that there exists $a > 0$ such that 
    \begin{align}
        \langle X, \mathcal{K}_f(X)\rangle_{\text{HS}} \geq a \|X\|_2^2
    \end{align}
    for every $X \in \mathcal{B}(\mathcal{H})$ satisfying $\langle \sqrt{\rho}, X \rangle_{\text{HS}} = 0.$
    Then 
    \begin{align}
        \text{gap}(\mathcal{L}) \geq 2a.
    \end{align}

We first consider $\beta > 0$, and let $X$ be orthogonal to $\sqrt{\rho}$.
    To apply the assumed bound for $\mathcal{K}_f$ inside the average in \Cref{lem:D_average_rep}, we must check that the operators $e^{-isH} X e^{isH}$ satisfy the same orthogonality condition.
    Since $H$ commutes with $\sqrt{\rho}$ and $e^{isH}$ is unitary, 
    \begin{align}
        \langle \sqrt{\rho}, e^{-isH}X e^{isH}\rangle_{\text{HS}} = \langle \sqrt{\rho}, X\rangle_{\text{HS}} = 0, \quad \|e^{-isH}Xe^{isH}\|_2 = \|X\|_2.
    \end{align}
    The assumption of $\langle X, \mathcal{K}_f(X)\rangle_{\text{HS}} \geq a \|X\|_2^2$ then gives the same lower bound for every $s \in \mathbb R$: 
    \begin{align}
        \langle e^{-isH}Xe^{isH}, \mathcal{K}_f(e^{-isH}Xe^{isH}) \rangle_{\text{HS}} \geq a \|X\|_2^2.
    \end{align}
    Inserting this inequality into the averaging identity from \Cref{lem:D_average_rep} gives us 
    \begin{align}
        \langle X, \mathcal{D}(X) \rangle_{\text{HS}} &= 2 \int_{\mathbb R} \frac{2}{\beta} \sech\left(\frac{2\pi s}{\beta}\right) \langle e^{-isH} X e^{isH}, \mathcal{K}_f(e^{-isH}X e^{isH})\rangle_{\text{HS}} ds\\
        &\geq 2a \|X\|_2^2 \int_{\mathbb R} \frac{2}{\beta} \sech\left(\frac{2\pi s}{\beta}\right) ds\\
        &= 2a \|X\|_2^2, \label{eq:bound_quad_term}
    \end{align}
    The weight here is nonnegative and integrates to one.
    Moreover, the conjugations in the integrand preserve the Hilbert-Schmidt norm and fix $\sqrt{\rho}$. 

    For $\beta = 0$, the Gaussian filter becomes the identity, so
    \begin{align}
        A_i = \gamma_i, \quad B = 0, \quad \rho = I/d,
    \end{align}
    which gives us 
    \begin{align}
        \mathcal{D}(X) = \frac{1}{2} \sum_i [A_i,[A_i,X]] = 2\mathcal{K}_f(X),
    \end{align}
    so the same lower bound in \eqref{eq:bound_quad_term} holds.

    Since $\mathcal{D}$ is self-adjoint and annihilates $\sqrt{\rho}$, it admits an orthonormal eigenbasis containing $\sqrt{\rho}$.
    Every other eigenvector $X$, with eigenvalue $\lambda$, is orthogonal to $\sqrt{\rho}$. 
    Applying the bound in \eqref{eq:bound_quad_term} gives us 
    \begin{align}
        \lambda \|X\|_2^2 = \langle X, \mathcal{D}(X)\rangle_{\text{HS}} \geq 2a \|X\|_2^2,
    \end{align}
    and therefore $\lambda \geq 2a$.
    Lastly, the definition of $\mathcal{D}$ implies 
    \begin{align}
        \mathcal{L}(\rho^{1/4} X \rho^{1/4}) = -\lambda \rho^{1/4} X \rho^{1/4}.
    \end{align}
    The transformation $X\to \rho^{1/4} X \rho^{1/4}$ is invertible, so $\mathcal{D}$ and $-\mathcal{L}$ have the same eigenvalues. 
    Therefore, 
    \begin{align}
        \operatorname{gap}(\mathcal{L}) = \operatorname{gap}(\mathcal{D}) \geq 2a.
    \end{align}

\label{lem:commutator_identity}
    For SYK Hamiltonian $H$ and the maps $c_i$ and $\mathsf{M}(\widetilde\gamma,\widetilde\gamma^\dagger)_{ij}$ as defined in \eqref{eq:c_defn} and \eqref{eq:mdef} respectively, the following identity holds 
    \begin{align}
        c_i([H,X]) - [H, c_i(X)] = \sum_j \mathsf{M}(\widetilde\gamma,\widetilde\gamma^\dagger)_{ij}(c_j(X))
    \end{align}
    for every $X \in \mathcal{B}(\mathcal{H})$ and every $i$.

The Majorana relations and antisymmetry of the couplings give 
    \begin{align}
        [\gamma_i, H] = \frac{1}{3} \sum_{j,k,l} J_{ijkl}\gamma_j \gamma_k \gamma_l.
    \end{align}
    Since the Gibbs factors commute with $H$, conjugating this identity gives 
    \begin{align}
        [\widetilde{\gamma}_i, H] = \frac{1}{3} \sum_{j,k,l} J_{ijkl}\widetilde{\gamma}_j \widetilde{\gamma}_k \widetilde{\gamma}_l, \quad [\widetilde{\gamma}_i^\dagger, H] = \frac{1}{3} \sum_{j,k,l} J_{ijkl}\widetilde{\gamma}_j^\dagger \widetilde{\gamma}_k^\dagger \widetilde{\gamma}_l^\dagger.
    \end{align}
    Directly expanding $c_i$, we obtain 
    \begin{align}
         c_i([H,X]) - [H, c_i(X)] &= \frac{1}{2} \left([\widetilde{\gamma}_i, H]X - X[\widetilde{\gamma}_i^\dagger, H]\right)\\
         &= \frac{1}{6}\sum_{j,k,l} J_{ijkl} \left(\widetilde{\gamma}_j \widetilde{\gamma}_k \widetilde{\gamma_l}X - X\widetilde{\gamma}_j^\dagger \widetilde{\gamma_k}^\dagger \widetilde{\gamma}_l^\dagger\right).
    \end{align}
    Note that the difference of the two cubic products can be written in terms of the maps $c_j, c_k, c_l$:
    \begin{align}
        \widetilde{\gamma}_j \widetilde{\gamma}_k \widetilde{\gamma}_lX - X\widetilde{\gamma}_j^\dagger \widetilde{\gamma}_k^\dagger \widetilde{\gamma}_l^\dagger = 2\widetilde{\gamma}_j \widetilde{\gamma}_k c_l(X) + 2\widetilde{\gamma}_j c_k(X)\widetilde{\gamma}_l^\dagger + 2c_j(X)\widetilde{\gamma}_k^\dagger \widetilde{\gamma}_l^\dagger. 
    \end{align}
    To express every contribution in terms of $c_j(X)$, we rename the summation indices in the first two terms:
    \begin{align}
        \sum_{j,k,l} J_{ijkl}\widetilde{\gamma}_j \widetilde{\gamma}_k c_l(X) = \sum_{j,k,l} J_{iklj}\widetilde{\gamma}_k \widetilde{\gamma}_l c_j(X) = \sum_{j,k,l} J_{ijkl}\widetilde{\gamma}_k\widetilde{\gamma}_l c_j(X),
    \end{align}
    and similarly 
    \begin{align}
        \sum_{j,k,l} J_{ijkl} \widetilde{\gamma}_j c_k(X) \widetilde{\gamma}_l^\dagger = \sum_{j,k,l} J_{ikjl} \widetilde{\gamma}_k c_j(X) \widetilde{\gamma}_l^\dagger.
    \end{align}
    Here antisymmetry gives $J_{iklj} = J_{ijkl}$ for the cyclic permutation and $J_{ikjl} = -J_{ijkl}$ for the exchange of $j$ and $k$.
    The third term already contains $c_j(X)$.
    Combining these three terms then gives us 
    \begin{align}
        c_i([H,X]) - [H, c_i(X)] &= \frac{1}{3} \sum_{j,k,l} J_{ijkl} \left(\widetilde{\gamma}_k\widetilde{\gamma}_l c_j(X) - \widetilde{\gamma}_k c_j(X) \widetilde{\gamma}_l^\dagger + c_j(X)\widetilde{\gamma}_k^\dagger \widetilde{\gamma}_l^\dagger\right) \\
        &= \sum_j \mathsf{M}(\widetilde\gamma,\widetilde\gamma^\dagger)_{ij} (c_j(X)).
    \end{align}

\label{lem:filter_effect}
    If $0 \leq \beta J \leq \frac{1}{1000}$ and $\|\mathsf{M}(\widetilde\gamma,\widetilde\gamma^\dagger)\| \leq 150J$, then for every $X \in \mathcal{B}(\mathcal{H})$,
    \begin{align}
        \left(\sum_i \left\|c_i^f(X) - c_i(X)\right\|_2^2\right)^{1/2} \leq \frac{1}{14} \left(\sum_i \|c_i(X)\|_2^2\right)^{1/2}.
    \end{align}

At $\beta = 0$, we have $A_i = \widetilde{\gamma}_i = \gamma_i$, so $c_i^f = c_i$ and the desired bound directly follows. 
    Assume now $\beta > 0$.
    By the Gaussian Fourier identity 
    \begin{align}
        e^{-\beta^2 w^2 /8} = \frac{\sqrt{2/\pi}}{\beta} \int_{\mathbb R} e^{-2s^2/\beta^2} e^{isw} ds,
    \end{align}
    we can write 
    \begin{align}
        Y_i = \frac{\sqrt{2/\pi}}{\beta} \int_{\mathbb R} e^{-2s^2/\beta^2} e^{isH} \gamma_i e^{-isH} ds.
    \end{align}
    Since the Gibbs factors commute with Hamiltonian evolution, the same average maps $\widetilde{\gamma}_i$ to $A_i$.
    Therefore,
    \begin{align}
        c_i^f(X) = \frac{\sqrt{2/\pi}}{\beta} \int_{\mathbb R} e^{-2s^2/\beta^2} e^{isH} c_i\left(e^{-isH} X e^{isH}\right) e^{-isH}ds.
    \end{align}
     To estimate how much this average differs from the unfiltered $c_i(X)$, fix $X$ and write 
    \begin{align}
        v_i(s) = e^{isH} c_i(e^{-isH}X e^{isH}) e^{-isH}, \quad v(s) = (v_1(s), \ldots, v_N(s)).
    \end{align}
    Thus
    \begin{align}
        v(0) = (c_1(X), \ldots, c_N(X))
    \end{align}
    is the tuple of unfiltered jump differences, and its weighted average is the tuple of filtered jump differences.
    We first bound how much this tuple changes with $s$.
    Differentiating and using \Cref{lem:commutator_identity}, we obtain 
    \begin{align}
        v'_i(s) &= i e^{isH} \left([H, c_i(e^{-isH} X e^{isH})] - c_i([H, e^{-isH} X e^{isH}])\right) e^{-isH} \\
        &= -i \sum_j e^{isH} \mathsf{M}(\widetilde\gamma,\widetilde\gamma^\dagger)_{ij} \left(e^{-isH} v_j(s) e^{isH}\right) e^{-isH}.
    \end{align}
    Conjugating by $e^{isH}$ preserves the Hilbert-Schmidt norm of every component, so the assumed bound on the block operator $\mathsf{M}(\widetilde\gamma,\widetilde\gamma^\dagger)$ gives
    \begin{align}
        \|v'(s)\|_2 \leq \|\mathsf{M}(\widetilde\gamma,\widetilde\gamma^\dagger)\| \|v(s)\|_2 \leq 150J \|v(s)\|_2.
    \end{align}
    Applying Grönwall's inequality to $v(s)$ and $v(-s)$ for $s \geq 0$ gives 
    \begin{align}
        \|v(s)\|_2 \leq e^{150J|s|} \|v(0)\|_2.
    \end{align}
    Integrating the derivative bound along the interval between $0$ and $s$, we then obtain 
    \begin{align}\label{eq:bound_of_v_diff}
        \|v(s) - v(0)\|_2 \leq 150J \int_{0}^{|s|} e^{150Jr} dr \|v(0)\|_2 = \left(e^{150 J|s|} -1\right) \|v(0)\|_2.
    \end{align}
    We now use this bound to estimate the effect of filtering. 
    The Gaussian integral representation of $c_i^f(X)$ gives 
    \begin{align}
        \left(c_i^f(X)\right)_{i=1}^N = \frac{\sqrt{2/\pi}}{\beta} \int_{\mathbb R} e^{-2s^2/\beta^2} v(s) ds.
    \end{align}
    Because the Gaussian weight integrates to one, subtracting the unfiltered tuple gives 
    \begin{align}
        \left(c_i^f(X) - c_i(X)\right)_{i=1}^N = \frac{\sqrt{2/\pi}}{\beta} \int_{\mathbb R} e^{-2s^2/\beta^2} (v(s) - v(0)) ds.
    \end{align}
    By the triangle inequality and \eqref{eq:bound_of_v_diff}, we get 
    \begin{align}
        \left(\sum_i \|c_i^f(X) - c_i(X)\|_2^2\right)^{1/2} &\leq \frac{\sqrt{2/\pi}}{\beta} \int_{\mathbb R} e^{-2s^2/\beta^2} \|v(s) - v(0)\|_2 ds\\
        &\leq \left(\sum_i \|c_i(X)\|_2^2\right)^{1/2} \frac{\sqrt{2/\pi}}{\beta} \int_{\mathbb R} e^{-2s^2/\beta^2} \left(e^{150J|s|}-1\right) ds,
    \end{align}
    where we also used $\|v(0)\|_2^2 = \sum_i \|c_i(X)\|_2^2$ for the last inequality. 
    It remains to bound the scalar integral. 
    Consider the bound
    \begin{align}
        &\frac{\sqrt{2/\pi}}{\beta}\int_{\mathbb R} e^{-2s^2/\beta^2} \left(e^{150J|s|} - 1\right) ds = \sqrt{\frac{2}{\pi}} \int_{0}^{\infty} e^{-r^2/2} \left(e^{75\beta Jr} - 1\right) dr\\
        &\leq \sqrt{\frac{2}{\pi}} \int_{0}^{\infty} e^{-r^2/2} \left(e^{3r/40} - 1\right) dr = e^{9/3200} \left(1 + \sqrt{\frac{2}{\pi}} \int_{0}^{3/40} e^{-r^2/2} dr\right) - 1\\
        &\leq \frac{1 + (5/6) (3/40)}{1-9/3200} - 1 = \frac{209}{3191} < \frac{1}{14}.
    \end{align}
    Here, the first equality uses the symmetry of the integrand and the substitution $r = 2s/\beta$.
    The first inequality follows from the assumption $\beta J \leq 1/1000$, which gives $75\beta J \leq 3/40$.
    The next equality follows by completing the square,
    \begin{align}
        -\frac{r^2}{2} + \frac{3r}{40} = -\frac{1}{2} \left(r-\frac{3}{40}\right)^2 + \frac{9}{3200}.
    \end{align}
    Lastly, the second inequality uses $e^{-r^2/2} \leq 1$, $\sqrt{2/\pi} < 5/6$, and $e^x \leq (1-x)^{-1}$ for $0 \leq x < 1$, applied at $x = 9/3200$.
    This completes the proof.

\label{cor:pseudo_comparisons}
    If $0\leq\beta J \leq 1/1000$ and $\|\mathsf{M}(\widetilde\gamma,\widetilde\gamma^\dagger)\| \leq 150 J$, then for every $X \in \mathcal{B}(\mathcal{H})$, 
\begin{align}
    \langle X, \mathcal{K}_f(X)\rangle_{\text{HS}} \geq \left(\frac{13}{14}\right)^2 \langle X, \mathcal{K}(X) \rangle_{\text{HS}}.
\end{align}
Moreover, $\ker{\mathcal{K}_f} = \ker{\mathcal{K}}$.

From \Cref{lem:filter_effect} and by the reverse triangle inequality 
    \begin{align}
        \left(\sum_i \left\|c_i^f(X)\right\|_2^2\right)^{1/2} &\geq \left(\sum_i \|c_i(X)\|_2^2\right)^{1/2} - \left(\sum_i \|c_i^f(X) - c_i(X)\|_2^2\right)^{1/2}\\ &\geq \frac{13}{14} \left(\sum_i \|c_i(X)\|_2^2\right)^{1/2}.
    \end{align}
    Squaring and using the definitions of $\mathcal{K}_f$ and $\mathcal{K}$, we obtain 
    \begin{align}\label{eq:K_Kf_relation}
        \langle X, \mathcal{K}_f(X)\rangle_{\text{HS}} &= \sum_i \left\|c_i^f(X)\right\|_2^2 \geq \left(\frac{13}{14}\right)^2 \sum_i \|c_i(X)\|_2^2 = \left(\frac{13}{14}\right)^2 \langle X, \mathcal{K}(X) \rangle_{\text{HS}}.
    \end{align}
    For both of the pseudo-Lindbladians, an operator belongs to one's kernel exactly when all the corresponding maps $c_i$ or $c_i^f$ send it to zero. 
    \eqref{eq:K_Kf_relation} then gives us $\ker \mathcal{K}_f \subseteq \ker \mathcal{K}$.
    Conversely, if $X \in \ker \mathcal{K}$, then $c_i(X) = 0$ for every $i$. 
    \Cref{lem:filter_effect} then gives 
    \begin{align}
        \left(\sum_i \left\|c_i^f(X)\right\|_2^2\right)^{1/2} = 0,
    \end{align}
    so $X \in \ker \mathcal{K}_f$. 
    This completes the proof.

\label{lem:aux_majorana_map}
    Consider the maps
    \begin{align}
        b_i(X) = \frac{1}{2} \left(\widetilde{\gamma}_i X - \mathcal{P}(X) \widetilde{\gamma}_i^\dagger\right).
    \end{align}
    They satisfy 
    \begin{align}
        \{b_i, b_j\} = 0, \quad \{b_i, b_j^\dagger\}(X) = \frac{1}{4}\left(\{\widetilde\gamma_i,\widetilde\gamma_j^\dagger\} X + X\{\widetilde\gamma_j, \widetilde\gamma_i^\dagger\}\right).
    \end{align}
    Moreover, 
    \begin{align}
        \bigcap_{i=1}^N \ker b_i = \operatorname{span}\{\sqrt{\rho}\}.
    \end{align}

Since $H$ is even, both $\widetilde{\gamma}_i$ and $\widetilde{\gamma}_i^\dagger$ are odd.
    Consequently, $\mathcal{P}$ anticommutes with their left and right multiplication maps, and
    \begin{align}
        b_i^\dagger(X) &= \frac{1}{2}\left(\widetilde\gamma_i^\dagger X + \mathcal{P}(X) \widetilde\gamma_i\right)\\
        \{b_i, b_j\}(X) &= \frac{1}{4}\left(\{\widetilde\gamma_i, \widetilde\gamma_j\} X - X \{\widetilde\gamma_i^\dagger, \widetilde\gamma_j^\dagger\}\right) = 0\\
        \{b_i, b_j^\dagger\}(X) &= \frac{1}{4}\left(\{\widetilde\gamma_i, \widetilde\gamma_j^\dagger\}X + X\{\widetilde\gamma_j, \widetilde\gamma_i^\dagger\}\right).
    \end{align}
    To identify the common kernel, observe that the Gibbs factors commute with physical parity, so 
    \begin{align}
        b_i\left(e^{-\beta H/4}X e^{-\beta H/4}\right) = \frac{1}{2} e^{-\beta H/4} \left(\gamma_i X - \mathcal{P}(X)\gamma_i\right) e^{-\beta H/4}.
    \end{align}
    For a Majorana monomial $\gamma_S$, 
    \begin{align}
        \frac{1}{2} (\gamma_i \gamma_S - \mathcal{P}(\gamma_S)\gamma_i) = 
        \begin{cases}
            \gamma_i \gamma_S, &i\in S\\
            0, &i\notin S.
        \end{cases}
    \end{align}
    For fixed $i$, the nonzero outputs have distinct supports $S \backslash \{i\}$, so they cannot cancel in a linear combination.
    Therefore, vanishing for every $i$ then forces every coefficient of a nonempty Majorana monomial to be zero.
    The common kernel of the maps inside the Gibbs factors is therefore $\operatorname{span}\{I\}$.
    The transformation $X \to e^{-\beta H/4} X e^{-\beta H/4}$ is invertible and sends $I$ to $e^{-\beta H/2}.$
    Therefore, 
    \begin{align}
        \bigcap_{i}\ker b_i = \operatorname{span}\{e^{-\beta H/2}\} = \operatorname{span}\{\sqrt{\rho}\}.
    \end{align}

\label{lem:curvature_implies_gap}
If $\|D\gamma(\beta/2)- I\| \leq \frac{1}{4},$ then for every $X \in \mathcal{B}(\mathcal{H})$ satisfying $\langle\sqrt{\rho}, X \rangle_{\text{HS}} = 0$, 
\begin{align}
    \langle X, \mathcal{K}(X) \rangle_{\text{HS}} \geq \frac{3}{4} \|X\|_2^2.
\end{align}
In particular, $\ker \mathcal{K} = \operatorname{span}\{\sqrt{\rho}\}$ and $\operatorname{gap}(\mathcal{K}) \geq \frac{3}{4}$.

By \eqref{eq:sim} and the Hermiticity of the block matrix $\left[\{\widetilde\gamma_i, \widetilde\gamma_j^\dagger\}\right]$, we can bound the spectrum of the following block matrix:
    \begin{align}
        {\rm spec}\left(\left[\frac{1}{2}\{\widetilde\gamma_i,\widetilde\gamma_j^\dagger\}\right]\right) = {\rm spec}(D\gamma(\beta/2)) \subseteq [3/4, 5/4], \quad \left[\frac{1}{2}\{\widetilde\gamma_i,\widetilde\gamma_j^\dagger\}\right] \geq \frac{3}{4}I.
    \end{align}
    Applying the bound to the columns of $X_i$ and of $X_i^\dagger$, \Cref{lem:aux_majorana_map} gives
    \begin{align}
        \sum_{i,j} \langle X_i, \{b_i, b_j^\dagger\}(X_j)\rangle_{\rm HS} = \frac{1}{4}\sum_{i,j}\left(\Tr[X_i^\dagger\{\widetilde\gamma_i,\widetilde\gamma_j^\dagger\}X_j] + \Tr[X_i\{\widetilde\gamma_i,\widetilde\gamma_j^\dagger\}X_j^\dagger]\right) \geq \frac{3}{4} \sum_i \norm{X_i}_2^2.\label{eq:tuple_inequality}
    \end{align}
    We first use this inequality to bound the following positive auxiliary operator
    \begin{align}\label{eq:defn_K_tilde}
        \widetilde{\mathcal{K}} = \sum_{i} b_i^\dagger b_i,\quad \langle X, \widetilde{\mathcal{K}}(X)\rangle_{\text{HS}} = \sum_i \|b_i(X)\|_2^2.
    \end{align}
    The relations $b_i b_j = -b_j b_i$ give 
    \begin{align}
        \widetilde{\mathcal{K}}^2 = \sum_{i,j} b_i^\dagger \left(\{b_i, b_j^\dagger\} - b_j^\dagger b_i\right) b_j = \sum_{i,j} b_i^\dagger \{b_i, b_j^\dagger\} b_j + \sum_i b_i^\dagger \widetilde{\mathcal{K}} b_i.
    \end{align}
    Combining \eqref{eq:tuple_inequality} and positivity of $\widetilde{\mathcal{K}}$, we can then get 
    \begin{align}
        \langle X, \widetilde{\mathcal{K}}^2(X) \rangle_{\text{HS}} \geq \frac{3}{4} \sum_i \|b_i(X)\|_2^2 = \frac{3}{4} \langle X, \widetilde{\mathcal{K}}(X) \rangle_{\text{HS}}.
    \end{align}
    For an eigenvector of $\widetilde{\mathcal{K}}$ with eigenvalue $\lambda > 0$, this inequality becomes $\lambda^2 \geq \frac{3}{4}\lambda$, and hence $\lambda \geq 3/4$.
    \Cref{lem:aux_majorana_map} and the sum-of-squares definition in \eqref{eq:defn_K_tilde} imply 
    \begin{align}
        \ker \widetilde{\mathcal{K}} = \bigcap_i \ker b_i = \operatorname{span} \{\sqrt{\rho}\}.
    \end{align}
    Expanding in an orthonormal eigenbasis then gives
    \begin{align}
        \langle X, \widetilde{\mathcal{K}}(X)\rangle_{\text{HS}} \geq \frac{3}{4} \|X\|_2^2,
    \end{align}
    for $X \perp \sqrt{\rho}$.
    It remains to transfer this bound to $\mathcal{K}$.
    For even $X$, the definitions give $b_i(X) = c_i(X)$, so the bound follows immediately.
    For odd $X$, multiplication by physical parity gives
    \begin{align}
        b_i(XP_f) = c_i(X) P_f.
    \end{align}
    The operator $XP_f$ is also odd, and is therefore orthogonal to the even operator $\sqrt{\rho}$.
    Since multiplication by $P_f$ preserves the Hilbert-Schmidt norm, 
    \begin{align}
        \langle X, \mathcal{K}(X)\rangle_{\text{HS}} &= \sum_i \|c_i(X)\|_2^2  = \sum_i \|b_i(XP_f)\|_2^2 \geq \frac{3}{4}\|XP_f\|_2^2 = \frac{3}{4} \|X\|_2^2.
    \end{align}
    Finally, every $X\perp \sqrt{\rho}$ decomposes into $(X+\mathcal{P}(X))/2$ and $(X-\mathcal{P}(X))/2$, both orthogonal to $\sqrt{\rho}$.
    Each $c_i$ reverses operator parity, so its outputs on these two components are orthogonal.
    Adding their bounds gives 
    \begin{align}
        \langle X, \mathcal{K}(X)\rangle_{\text{HS}} \geq \frac{3}{4} \left(\norm{\frac{X+\mathcal{P}(X)}{2}}_2^2 + \norm{\frac{X-\mathcal{P}(X)}{2}}_2^2\right) = \frac{3}{4} \|X\|_2^2.
    \end{align}
    Since $\mathcal{K}(\sqrt{\rho}) = 0$, this also identifies its kernel and proves the asserted spectral gap.

\label{lem:jacob}
    For integers $m,p\geq1$, the coefficients in \eqref{eq:fm} satisfy
    \begin{align}
        \frac{1}{d}\mathbb E_J\Tr[(F_m^\dagger F_m)^p]
        \leq\mathbb E_J\Tr[(\widetilde F_m(\mathbf1)^\dagger\widetilde F_m(\mathbf1))^p].
    \end{align}

To easily evaluate the expectation over Gaussian disorder, we group terms by the Hamiltonian coefficients $J_A$. Let $\alpha_A$ record the number of times each $J_A$ appears; we write $J^\alpha = \prod_A J_A^{\alpha_A}$ and $|\alpha| = \sum_A \alpha_A$. Using
    \begin{align}
        \partial_i(\gamma_{w_1}\cdots\gamma_{w_L}) = \sum_{a=1}^L (-1)^{a-1} \delta_{i,w_a} \gamma_{w_1}\cdots\gamma_{w_{a-1}}\gamma_{w_{a+1}}\cdots\gamma_{w_L},
    \end{align}
    we have for $m=|\alpha|$ by applying the triangle inequality on \eqref{eq:hgam} and comparing the terms to \eqref{eq:hx} (noting the norm of a Majorana string is 1) that
    \begin{align}
        \left\|
            [J^\alpha]\partial_i\operatorname{ad}_H^m\gamma_j
        \right\|
        &\leq
        [J^\alpha]\partial_{x_i}
        (2\nabla G\cdot\nabla)^m x_j
        \bigg|_{x=\mathbf 1}.
    \end{align}
    Since $\operatorname{ad}_H^m\gamma_j$ is odd, \eqref{eq:fm} then gives
    \begin{align}
        \norm{[J^\alpha](F_m)_{ji}}
        &=
        \frac{1}{m!}
        \left\|
            [J^\alpha]\partial_i\operatorname{ad}_H^m\gamma_j
        \right\| \leq
        \frac{1}{m!}
        [J^\alpha]\partial_{x_i}
        (2\nabla G\cdot\nabla)^m x_j
        \bigg|_{x=\mathbf 1} =
        [J^\alpha](\widetilde F_m(\mathbf 1))_{ji}.
    \end{align}
    Each entry of $F_m$ is homogeneous of degree $m$ in the couplings, and
    $\mathbb E_J J^{\alpha_1+\cdots+\alpha_{2p}}\geq0$.
    With $i_{p+1}=i_1$, we obtain
    \begin{align}\label{eq:gaussian_trace_expansion}
        &\frac{1}{d}\mathbb E_J\Tr[(F_m^\dagger F_m)^p]\notag\\
        &=\sum_{i,j\in[N]^p}
          \sum_{|\alpha_1|=\cdots=|\alpha_{2p}|=m}
          \mathbb E_J J^{\sum_r\alpha_r}\,
          \frac{1}{d}\operatorname{Re}\Tr\prod_{r=1}^p
          \left(\bigl([J^{\alpha_{2r-1}}](F_m)_{j_ri_r}\bigr)^\dagger
          [J^{\alpha_{2r}}](F_m)_{j_ri_{r+1}}\right)\notag\\
        &\leq\sum_{i,j\in[N]^p}
          \sum_{|\alpha_1|=\cdots=|\alpha_{2p}|=m}
          \mathbb E_J J^{\sum_r\alpha_r}\,
          \prod_{r=1}^p
          [J^{\alpha_{2r-1}}](\widetilde F_m(\mathbf1))_{j_ri_r}
          [J^{\alpha_{2r}}](\widetilde F_m(\mathbf1))_{j_ri_{r+1}}\\
        &=\mathbb E_J\Tr[(\widetilde F_m(\mathbf1)^T\widetilde F_m(\mathbf1))^p].\notag
    \end{align}
    The inequality uses $|\Tr Z|\leq d\|Z\|$, submultiplicativity of the
    operator norm, and the coefficient bound above.

\label{lem:classical}
    For integers $m, p \geq 1$ with $mp \leq 7N$,
    \begin{align}
        \left(\mathbb E_J \norm{\widetilde F_m(\mathbf 1)}^{2p}\right)^{1/(2p)} \leq (105J)^m.
    \end{align}

\label{cor:fbound}
    For integers $m, p \geq 1$ with $mp \leq 7N$, the operators in \eqref{eq:fm} satisfy
    \begin{align}
        \mathbb E \norm{F_m}^{2p} \leq Nd(105 J)^{2pm}.
    \end{align}

By \Cref{lem:jacob,lem:classical},
    \begin{align}
        \mathbb E\|F_m\|^{2p} \leq\mathbb E\Tr[(F_m^\dagger F_m)^p] \leq d\mathbb E\Tr[(\widetilde F_m(\mathbf 1)^\dagger\widetilde F_m(\mathbf 1))^p] \leq Nd\mathbb E\|\widetilde F_m(\mathbf 1)\|^{2p}
        \leq Nd(105J)^{2pm}.
    \end{align}

\label{lem:m_jacobian}
    For an integer $m\geq0$, let $M_m=[s^m]\mathsf M(\gamma(s),\gamma(-s))$.
    Then for every integer $p\geq1$,
    \begin{align}
        \frac{1}{d^2}\mathbb E_J\Tr[(M_m^\dagger M_m)^p]
        \leq(m+1)^{2p}\mathbb E_J\Tr[(\widetilde F_{m+1}(\mathbf1)^\dagger
          \widetilde F_{m+1}(\mathbf1))^p].
    \end{align}
    Here the first trace is on $\mathbb C^N\otimes\mathcal{B}(\mathcal{H})$ and the second is on $\mathbb C^N$.

We use the same word expansion as in \Cref{lem:jacob}, now before taking the fermionic derivative.
    Its coefficient bound is
    \begin{align}\label{eq:word_coefficient_bound}
        \|[s^rJ^\alpha]\gamma_i(\pm s)\|
        \leq[s^rJ^\alpha]x_i(s;\mathbf1),
        \qquad |\alpha|=r.
    \end{align}
    The right side is nonnegative. For each term in \eqref{eq:mdef}, use
    $\|X\mapsto AXB\|_{2\to2}\leq\|A\|\|B\|$.
    For $i\neq j$, the three terms and the factor $1/3$ give
    \begin{align}\label{eq:m_hessian_coefficients}
        \|[J^\alpha](M_m)_{ij}\|_{2\to2}
        &\leq[s^mJ^\alpha]
          \sum_{\substack{k,l\\i,j,k,l\ \mathrm{distinct}}}
          J_{\{i,j,k,l\}}x_k(s;\mathbf1)x_l(s;\mathbf1) =[s^mJ^\alpha]\bigl(2\nabla^2G(x(s;\mathbf1))\bigr)_{ij}.
    \end{align}
    For $i=j$, both sides of \eqref{eq:m_hessian_coefficients} vanish.
    Every coefficient of $x_i(s;\mathbf1)$, $Dx(s;\mathbf1)-I$, and $2\nabla^2G(x(s;\mathbf1))$ is nonnegative.
    Thus \eqref{eq:classical_variation} gives, for $|\alpha|=m+1$,
    \begin{align}\label{eq:m_derivative_coefficients}
        [s^mJ^\alpha]\bigl(2\nabla^2G(x(s;\mathbf1))\bigr)_{ij}
        &\leq[s^mJ^\alpha]
             \bigl(2\nabla^2G(x(s;\mathbf1))Dx(s;\mathbf1)\bigr)_{ij} =[s^mJ^\alpha]\partial_s(Dx)_{ij}(s;\mathbf1) \\
        &=(m+1)[J^\alpha](\widetilde F_{m+1}(\mathbf1))_{ij}.
    \end{align}
    Combining \eqref{eq:m_hessian_coefficients} and \eqref{eq:m_derivative_coefficients},
    \begin{align}\label{eq:m_coefficient_comparison}
        \|[J^\alpha](M_m)_{ij}\|_{2\to2}
        \leq(m+1)[J^\alpha](\widetilde F_{m+1}(\mathbf1))_{ij}.
    \end{align}
    Each block of $M_m$ is homogeneous of degree $m+1$ in the couplings.
    Apply the trace expansion \eqref{eq:gaussian_trace_expansion} with blocks
    acting on the $d^2$-dimensional Hilbert-Schmidt space.
    Using \eqref{eq:m_coefficient_comparison} and nonnegativity of the Gaussian moments,
    \begin{align}
        &\frac{1}{d^2}\mathbb E_J\Tr[(M_m^\dagger M_m)^p]\notag\\
        &\leq(m+1)^{2p}\sum_{i,j\in[N]^p}
          \sum_{|\alpha_1|=\cdots=|\alpha_{2p}|=m+1}
          \mathbb E_J J^{\sum_r\alpha_r}\,
          \prod_{r=1}^p
          [J^{\alpha_{2r-1}}](\widetilde F_{m+1}(\mathbf1))_{j_ri_r}
          [J^{\alpha_{2r}}](\widetilde F_{m+1}(\mathbf1))_{j_ri_{r+1}}\notag\\
        &=(m+1)^{2p}\mathbb E_J\Tr[(\widetilde F_{m+1}(\mathbf1)^T
          \widetilde F_{m+1}(\mathbf1))^p],
    \end{align}
    where $i_{p+1}=i_1$.

\label{cor:mbound}
    For integers $m \geq 0, p \geq 1$ with $(m+1)p \leq 7N$,
    \begin{align}
        \mathbb E \norm{M_m}^{2p} \leq Nd^2 (m+1)^{2p} (105J)^{2p(m+1)}.
    \end{align}

By \Cref{lem:m_jacobian,lem:classical},
    \begin{align}
        \mathbb E\|M_m\|^{2p}
        \leq\mathbb E\Tr[(M_m^\dagger M_m)^p]
        \leq Nd^2(m+1)^{2p}\mathbb E\|\widetilde F_{m+1}(\mathbf 1)\|^{2p}
        \leq Nd^2(m+1)^{2p}(105J)^{2p(m+1)}.
    \end{align}

\label{cor:jacobian_high_probability}
    With probability at least $1-2e^{-N}$ over the disorder, $\|H\|\leq2JN$ and, simultaneously for every real $s$ with $133J|s|<1$,
    \begin{align}\label{eq:uniform_jacobian_bounds}
        \|D\gamma(s)-I\|&\leq\frac{133J|s|}{1-133J|s|},
        \qquad \|\mathsf M(\gamma(s),\gamma(-s))\|
        \leq\frac{133J}{(1-133J|s|)^2}.
    \end{align}

For each $1\leq m\leq N$, take $p=\lceil6N/m\rceil$, so $6N\leq pm\leq7N$.
    By \Cref{cor:fbound,cor:mbound} and Markov's inequality,
    \begin{align}
        \Pr\left[\exists m\in[N]:
          \max\{\|F_m\|,\|M_{m-1}\|/m\}>(133J)^m\right] \leq N^2(d+d^2)(105/133)^{12N}
         \leq2\cdot4^{-N}.
    \end{align}
    Intersect this event's complement with $\{\|H\|\leq2JN\}$;
    by \Cref{fac:norm}, the latter event fails with probability at most $2^{-5N/2}$.
    For $m>N$, the bound $m!\geq(m/e)^m$ gives
    \begin{align}
        \|F_m\|
        &\leq\frac{N(2\|H\|)^m}{m!}
         \leq N\left(\frac{4eJN}{m}\right)^m
         \leq N(4eJ)^m\leq(133J)^m.
    \end{align}
    The identity $\mathsf M(\gamma(s),\gamma(-s))_{ij}(X)=e^{-sH}(M_0)_{ij}(e^{sH}Xe^{sH})e^{-sH}$ and $\|M_0\|\leq133J$ imply, for $r\geq N$,
    \begin{align}
        \|M_r\|
        &\leq\|M_0\|\sum_{a_1+\cdots+a_4=r}
          \frac{\|H\|^r}{a_1!\cdots a_4!}
         =\|M_0\|\frac{(4\|H\|)^r}{r!} \leq133J\left(\frac{8eJN}{r}\right)^r
         \leq(r+1)(133J)^{r+1}.
    \end{align}
    Thus, on a single event of probability at least
    $1-2\cdot4^{-N}-2^{-5N/2}\geq1-2e^{-N}$,
    \begin{align}
        \|F_m\|\leq(133J)^m,
        \qquad \|M_{m-1}\|\leq m(133J)^m,
        \qquad m\geq1.
    \end{align}
    Summing the series gives
    \begin{align}
        \|D\gamma(s)-I\|
        &\leq\sum_{m\geq1}(133J|s|)^m
         =\frac{133J|s|}{1-133J|s|},\\
        \|\mathsf M(\gamma(s),\gamma(-s))\|
        &\leq\sum_{m\geq1}|s|^{m-1}m(133J)^m
         =\frac{133J}{(1-133J|s|)^2}.
    \end{align}

On the event in \Cref{cor:jacobian_high_probability}, for $0\leq\beta J\leq1/1000$,
    \begin{align}
        \|D\gamma(\beta/2)-I\|
        &\leq\frac{133\beta J/2}{1-133\beta J/2}
         <\frac{1}{4},\\
        \|\mathsf M(\widetilde\gamma,\widetilde\gamma^\dagger)\|
        &\leq\frac{133J}{(1-133\beta J/4)^2}
         <150J.
    \end{align}
    Applying \Cref{lem:curvature_implies_gap,cor:pseudo_comparisons,lem:filtered_to_lind_gap},
    \begin{align}
        \operatorname{gap}(\mathcal{L})
        &\geq2\operatorname{gap}(\mathcal{K}_f)
         \geq2\left(\frac{13}{14}\right)^2\operatorname{gap}(\mathcal{K})
         \geq\frac{507}{392}>1,\\
        t_{\mathrm{mix}}(\epsilon)
        &\leq\frac{392}{507}\left(\frac{N}{4}\log2+2\beta JN+\log\frac{1}{\epsilon}\right)
         =O\left(N+\log\frac{1}{\epsilon}\right).
    \end{align}

For an integer $r\geq1$ and a symmetric $r$-linear form $T:(\mathbb R^n)^r\to\mathbb R$,
    \begin{align}
        \sup_{\|u_1\|=\cdots=\|u_r\|=1}|T(u_1,\ldots,u_r)|
        =\sup_{\|u\|=1}|T(u,\ldots,u)|.
    \end{align}

Put $\ell(G)=\sup_{\|x\|=1}|G(x)|$, which equals the multilinear norm
    by Banach's theorem. For real unit vectors $u,v$,
    \begin{align}
        \mathbb E_J(G(u)-G(v))^2
        &=\frac{6J^2}{N^3}\sum_{A\in\binom{[N]}4}(u_A-v_A)^2 \leq\frac{J^2}{4N^3}\|u^{\otimes4}-v^{\otimes4}\|^2
         =\frac{J^2}{2N^3}(1-\langle u,v\rangle^4)
         \leq\frac{J^2}{N^3}\|u-v\|^2.
    \end{align}
    Sudakov-Fernique compares $G(u)$ with
    $JN^{-3/2}\langle g,u\rangle$, where $g\sim\mathcal N(0,I_N)$.
    Since $G(e_1)=0$ and $G$ and $-G$ have the same law,
    \begin{align}
        \mathbb E_J\ell(G)
        &\leq2\mathbb E_J\sup_{\|u\|=1}G(u)
         \leq\frac{2J}{N^{3/2}}\mathbb E\|g\|
         \leq\frac{2J}{N},\qquad \sup_{\|u\|=1}\mathbb E_JG(u)^2
        \leq\frac{J^2}{4N^3}.
    \end{align}
    Apply Borell-TIS to the continuous Gaussian process
    $(\eta,u)\mapsto\eta G(u)$ on $\{\pm1\}\times S^{N-1}$.
    For $t\geq0$, we have $\Pr[\ell(G)>2J/N+t]\leq e^{-2N^3t^2/J^2}$. Integrating this tail gives, for every integer $k\geq1$,
    \begin{align}\label{eq:tensor_moment}
        \bigl(\mathbb E_J\ell(G)^{2k}\bigr)^{1/(2k)}
        &\leq\frac{2J}{N}
          +\left(2k\int_0^\infty t^{2k-1}e^{-2N^3t^2/J^2}\,dt\right)^{1/(2k)} \hspace{-0.5em} = \frac{2J}{N}+\frac{J(k!)^{1/(2k)}}{\sqrt2\,N^{3/2}}
         \leq\frac{J}{N}\left(2+\sqrt{\frac{k}{2N}}\right).
    \end{align}
    The polynomial $(2\nabla G\cdot\nabla)^m x$ has degree $2m+1$.
    Applying \eqref{eq:homogeneous_derivative_bound} to $G$ and then
    successively to these polynomials gives
    \begin{align}
        \sup_{\|x\|=1}\|(2\nabla G\cdot\nabla)^m x\|
        &\leq8\ell(G)(2m-1)
          \sup_{\|x\|=1}\|(2\nabla G\cdot\nabla)^{m-1}x\| \leq(8\ell(G))^m(2m-1)!!,\\
        \|\widetilde F_m(\mathbf 1)\|
        &=\frac1{m!}\left\|D\bigl((2\nabla G\cdot\nabla)^m x\bigr)
            \big|_{x=\mathbf 1}\right\| \leq\frac{(8N\ell(G))^m(2m+1)!!}{m!}
         \leq(24N\ell(G))^m.
    \end{align}
    Here $\|\mathbf 1\|=\sqrt N$ and
    $(2m+1)!!/m!=\prod_{r=1}^m(2+1/r)\leq3^m$.
    Taking $k=mp\leq7N$ in \eqref{eq:tensor_moment},
    \begin{align}
        \bigl(\mathbb E_J
             \|\widetilde F_m(\mathbf 1)\|^{2p}\bigr)^{1/(2p)}
        &\leq(24N)^m\bigl(\mathbb E_J\ell(G)^{2mp}\bigr)^{1/(2p)} \leq\left[24J\left(2+\sqrt{\frac{mp}{2N}}\right)\right]^m
        \leq(105J)^m.
    \end{align}
